/* Types */
/**
 *  A fault currently in effect: fired by the presenter (or a scenario, or restored at session
 *  start) and not yet cleared in Cumulocity (D9).
 */
export type ActiveFault = {
	target: FaultTarget,
	alarmType: string,
	/**  Cumulocity alarm id, once created. */
	alarmId: string | null,
	raisedAt: string,
	/**
	 *  Status of the alarm in Cumulocity (acknowledging changes only this; clearing ends the
	 *  fault).
	 */
	status: OpenAlarmStatus,
};

/**  One HTTP request made to Cumulocity. The log keeps the last 500, in memory only. */
export type ActivityEntry = {
	/**  Monotonic id within this app run. */
	id: number,
	/**  ISO-8601 request start time. */
	time: string,
	method: string,
	/**  Base URL of the tenant, e.g. `https://example.cumulocity.com` (for `to_curl`). */
	baseUrl: string,
	/**
	 *  Basic-auth user name as sent (`tenantId/user` on foreign domains). The password and
	 *  request headers are never stored.
	 */
	user: string,
	/**  Path + query, without host. */
	path: string,
	/**  HTTP status, `None` on transport error. */
	status: number | null,
	durationMs: number,
	/**  Shortened request body (≤ 2 kB; a curl built from a truncated body is incomplete). */
	requestBody: string | null,
	/**  Shortened response body (≤ 2 kB). */
	responseBody: string | null,
	/**  Transport error message, if any. */
	error: string | null,
};

/**  `activity-logged` — a request was added to the activity log. */
export type ActivityLogged = ActivityEntry;

/**  Serializable application error. Adjacently tagged: `{ "code": "...", "details": ... }`. */
export type AppError = 
/**  No user is logged in (call `login` first). */
{ code: "notAuthenticated" } | 
/**
 *  Cumulocity rejected the credentials (401 on `GET /user/currentUser`). `details` is the
 *  server's reason when it gave one ("User account is locked", "password expired" …).
 */
{ code: "authFailed"; details: string | null } | 
/**  Non-2xx response from Cumulocity. */
{ code: "http"; details: {
	status: number,
	message: string,
} } | 
/**  Transport-level failure (DNS, TLS, timeout, connection reset). */
{ code: "network"; details: string } | 
/**  A device, item, demo, scenario, operation … does not exist. */
{ code: "notFound"; details: string } | 
/**
 *  The request from the frontend is malformed or violates a rule
 *  (e.g. slave name > 19 chars, invalid raw JSON).
 */
{ code: "invalidInput"; details: string } | 
/**  The bundled library failed to load or validate. */
{ code: "library"; details: string } | 
/**  OS keychain access failed. */
{ code: "keychain"; details: string } | 
/**  A session command was issued while no session is running. */
{ code: "noSession" } | 
/**
 *  `start_session` was called while another session is running.
 *  `details` is the device id of the running session.
 */
{ code: "sessionActive"; details: string } | 
/**
 *  The device carries a fresh advisory lock from another user
 *  (`lw_demo.lock`, younger than 10 min). Retry with `force: true` to take over.
 */
{ code: "deviceLocked"; details: {
	user: string,
	since: string,
} } | 
/**  File system error (export, library resources). */
{ code: "io"; details: string } | 
/**  Anything else. Should be rare; prefer a specific variant. */
{ code: "internal"; details: string };

/**  Static information about the running app and its bundled library. */
export type AppInfo = {
	/**  App version (== library version, SemVer). */
	version: string,
	/**  Version of the bundled `library/` (from the app version, see PRD §11.1). */
	libraryVersion: string,
	/**  `macos` / `windows` / …. */
	platform: string,
};

