"impulseCounter" | 
/**  Plain input; sends `Value<NN>`. */
"measurement";

/**  Arguments of `export_demo_pack`. */
export type ExportRequest = {
	deviceId: string,
	/**  Demo id for the exported pack (`[a-z0-9-]`). */
	demoId: string,
	/**  Target folder; the export writes a `library/`-shaped tree inside it. */
	targetDir: string,
};

/**  Result of `export_demo_pack`. */
export type ExportResult = {
	path: string,
	filesWritten: string[],
	warnings: string[],
};

/**  `fault-changed` — a fault was raised or cleared. */
export type FaultChanged = {
	/**  Session revision after the change (`SessionSnapshot::revision`). */
	revision: number,
	deviceId: string,
	target: FaultTarget,
	/**  Present while raised, `None` once cleared. */
	fault: ActiveFault | null,
};

/**  One selectable fault (firmware text + severity), from `fault_catalog`. */
export type FaultDefinition = {
	target: FaultTarget,
	/**  Resolved Cumulocity alarm type. */
	alarmType: string,
	text: string,
	severity: Severity,
};

/**  Where a fault applies. Alarm types/texts/severities come from the fault catalog. */
export type FaultTarget = 
/**  Per-lamp native alarm, e.g. `lw_lampFailure_1_NN_openCircuit`. */
{ kind: "daliLamp"; lamp: number; alarmType: string } | 
/**  Bus-level alarm, e.g. `lw_daliBusPower*`. */
{ kind: "daliBus"; alarmType: string } | 
/**  Slave timeout: stops measurements, raises `lw_modbus_<id:02>_timeoutError`. */
{ kind: "slaveTimeout"; slaveKey: string } | 
/**  One custom alarm of a slave: `lw_demo_<id:02>_<alarmName>` (D2). */
{ kind: "slaveAlarm"; slaveKey: string; alarmName: string } | 
/**  A device-level `customAlarm` item: `lw_demo_<name>` (D2). */
{ kind: "customAlarm"; itemId: string } | 
/**
 *  Native alarm of a DALI brightness / motion sensor (`lw_brightness_1_NN_lost`, …).
 *  `sensorKind` because `kind` is the tag.
 */
{ kind: "sensor"; 
/**  `brightness` | `motion`. */
sensorKind: string; 
/**  Sensor 1–10. */
index: number; 
/**  Alarm type. */
alarm: string };

/**  Anything the raw fire panel can send; stored in the history for "resend". */
export type FireRequest = {
	kind: "measurement",
} & RawMeasurement | {
	kind: "alarm",
} & RawAlarm | {
	kind: "event",
} & RawEvent | {
	kind: "json",
} & RawJsonRequest;

/**  One entry of the raw-fire history. */
export type FiredRecord = {
	/**  Monotonic id within this app run. */
	id: number,
	deviceId: string,
	firedAt: string,
	request: FireRequest,
	/**  HTTP status of the POST. */
	status: number,
	/**  Id of the created measurement / alarm / event. */
	createdId: string | null,
};

/**  Reference to an `lw_floorplan` managed object. */
