/**  Value generator running on top of a control (PRD §8). */
export type GeneratorConfig = { kind: "randomWalk"; center: number; spread: number; step: number | null } | { kind: "sine"; 
/**  Period in seconds. */
period: number; amplitude: number; 
/**  Center line; defaults to the control default. */
center: number | null } | { kind: "dailyProfile"; 
/**  Exactly 24 hourly points (local time), linearly interpolated. */
points: number[] } | { kind: "counter"; ratePerHour: number };

/**  DALI group mode (`lw_switchGroupMode`). */
