/**  Resolved Cumulocity naming of an item's measurement. */
export type MeasurementNaming = {
	/**  e.g. `daliControlGear`, `digitalInput`, `modbus`, `c8y_SignalStrength`. */
	type: string,
	/**  e.g. `LW Dali Control Gear 1-03`, `LW_Modbus_Slave_20_240`, `LW Digital Input`. */
	fragment: string,
	/**
	 *  All series under the fragment. One entry for most items; a DALI lamp has four
	 *  (`Converter Status`, `Lamp Status`, `Converter Runtime`, `Brightness`). The item's value
	 *  is the single series, or `Brightness` for a DALI lamp.
	 */
	series: SeriesNaming[],
};

/**  Modbus register data type. */
export type ModbusDatatype = "int16" | "uint16" | "int32" | "uint32" | "float32";

/**
 *  Modbus register type (`lw_configModbusSlaves[].registers[].type`).
 *  `discrete` exists in the firmware but is not simulated.
 */
export type ModbusRegisterType = "coil" | "holding" | "input";

/**
 *  Status of an open Cumulocity alarm (DECISIONS D9). A CLEARED alarm is no longer open: its
 *  fault ends.
 */
export type OpenAlarmStatus = "ACTIVE" | "ACKNOWLEDGED";

/**  Presenter decision for a visible operation. */
export type OperationDecision = { decision: "confirm" } | 
/**  `reason` becomes the `failureReason` (default `Aborted by user`). */
{ decision: "abort"; reason?: string | null };

/**  The parameters of a visible operation, for the UI to word in the current language. */
export type OperationDetail = { kind: "groupMode"; group: number; mode: GroupMode } | { kind: "converterState"; converter: number; on: boolean } | { kind: "modbusWrite"; slaveAddress: number; registerAddress: number; value: number; coil: boolean; 
/**  Title of the library item behind the register, if known. */
itemTitle: LocalizedText | null };

/**  A visible operation waiting for Confirm / Abort. Emitted as `operation-prompt`. */
export type OperationPrompt = {
	/**  Session revision when the prompt was raised (see `SessionSnapshot::revision`). */
	revision: number,
	deviceId: string,
	operationId: string,
	kind: VisibleOperationKind,
	/**
	 *  Technical English summary built in Rust (e.g. `Group 3 → On`): for logs and as a
	 *  fallback. The UI words the prompt from `detail` in the current language.
	 */
	summary: string,
	detail: OperationDetail,
	/**  `lw_*.by` of the operation, else `creationRequest.user` / `user`, if present. */
	by: string | null,
	receivedAt: string,
	/**  `received_at + 60 s`; after this the backend fails it with "Timed out". */
	expiresAt: string,
};

/**  `operation-prompt` — a visible operation needs Confirm / Abort (60 s). */
export type OperationPromptEvent = OperationPrompt;

/**  Why an operation reached its final state. */
export type OperationResolution = 
/**  Config operation, answered without a prompt. */
"autoAnswered" | 
/**  Auto-accept switch was on. */
"autoAccepted" | "confirmed" | "aborted" | "timedOut" | 
/**  Stale PENDING operation found at session start. */
"simulatorOffline" | 
/**  Applying the effect failed. */
"error" | 
/**
 *  The operation became final elsewhere while its prompt was open (the plugin cancelled it
 *  or another client answered); the prompt was withdrawn. `status` / `reason` are what was
 *  observed.
 */
"withdrawn" | 
/**
 *  The presenter stopped the session while the prompt was open (the operation is FAILED
 *  "Simulator stopped"). Not an error: the UI shows nothing.
 */
"stopped";

/**  An operation reached SUCCESSFUL / FAILED. Emitted as `operation-resolved`. */
export type OperationResolved = {
	/**  Session revision after the resolution (see `SessionSnapshot::revision`). */
	revision: number,
	deviceId: string,
	operationId: string,
	/**  Cumulocity fragment name, e.g. `lw_fetchCore`. */
	operationType: string,
	status: OperationStatus,
	resolution: OperationResolution,
	/**  `failureReason` sent to Cumulocity, if failed. */
	reason: string | null,
};

/**  `operation-resolved` — an operation reached SUCCESSFUL / FAILED. */
export type OperationResolvedEvent = OperationResolved;

/**  Final operation status reported back to Cumulocity. */
export type OperationStatus = "PENDING" | "EXECUTING" | "SUCCESSFUL" | "FAILED";

/**  `c8y_Position`. */
export type Position = {
	lat: number,
	lng: number,
	alt?: number,
};

export type RawAlarm = {
	type: string,
	severity: Severity,
	text: string,
};

export type RawEvent = {
	type: string,
	text: string,
	/**  Optional JSON object (as text) merged into the event body. */
	extraJson: string | null,
};

/**  `raw-fired` — a raw-fire request completed (history entry). */
export type RawFired = FiredRecord;

/**  Raw JSON body to POST. `source.id` is filled with the selected device if missing. */
export type RawJsonRequest = {
	target: RawTarget,
	/**  JSON object as text, exactly as typed by the user. */
	body: string,
};

/**  A single-series measurement to fire. */
export type RawMeasurement = {
	type: string,
	fragment: string,
	series: string,
	value: number,
	unit: string | null,
};

/**  Target API for the raw-JSON tab. */
export type RawTarget = "measurement" | "alarm" | "event";

/**  `realtime-status` — Cumulocity realtime (operations) connection state. */
export type RealtimeStatus = {
	/**  Session revision (see `SessionSnapshot.revision`). */
	revision: number,
	deviceId: string,
	connected: boolean,
	error: string | null,
};

/**  Address assigned to one Modbus register (item). Persisted so upgrades never renumber. */
export type RegisterAssignment = {
	/**  Item id (== register name). */
	itemId: string,
	registerType: ModbusRegisterType,
	/**  Raw register address 0–65535 (`registers[].address`, `lw_modbusWrite.registerAddress`). */
	address: number,
};

/**  Arguments of `reset_demo_device`. */
export type ResetDeviceRequest = {
	/**  Also delete floorplans the app created (`lw_demo.floorplanIds`). */
	deleteFloorplans: boolean,
};

/**  A credential stored in the keychain (the password never leaves Rust). */
export type SavedLogin = {
	tenant: Tenant,
	username: string,
};

/**  Named preset (PRD §8). */
export type Scenario = Scenario_Serialize | Scenario_Deserialize;

/**  One step of a scenario (PRD §8): set a value, set a generator, or raise / clear a fault. */
export type ScenarioStep = { kind: "value"; itemId: string; value: number } | { kind: "generator"; itemId: string; generator: GeneratorConfig } | 
/**  `true` raises, `false` clears. */
{ kind: "fault"; target: FaultTarget; active: boolean };

/**  Named preset (PRD §8). */
export type Scenario_Deserialize = {
	id: string,
	name: LocalizedText,
	/**  What the scenario shows (shown where scenarios are picked). Optional. */
	description?: LocalizedText | null,
	/**  Applied automatically on session start. */
	start?: boolean,
	set: ScenarioStep[],
};

/**  Named preset (PRD §8). */
export type Scenario_Serialize = {
	id: string,
	name: LocalizedText,
	/**  What the scenario shows (shown where scenarios are picked). Optional. */
	description?: LocalizedText | null,
	/**  Applied automatically on session start. */
	start: boolean,
	set: ScenarioStep[],
};

/**  One option of a `select` control. */
export type SelectOption = {
	value: number,
	label: LocalizedText,
};

/**  One series of a measurement: name plus the unit the firmware sends (`None` = omit `unit`). */
export type SeriesNaming = {
	/**  e.g. `Brightness`, `Value03`, `freezer_temp`. */
	name: string,
	unit: string | null,
};

/**
 *  `session-changed` — session lifecycle or configuration changed
 *  (start, stop, auto-accept, interval, group modes). `None` = no session.
 */
export type SessionChanged = SessionSnapshot | null;

/**
 *  `session-error` — non-fatal or fatal problem inside the session task.
 *  `code` matches an `AppError` code for i18n.
 */
export type SessionError = {
	code: string,
	message: string,
	/**  The session stopped because of it. */
	fatal: boolean,
};

/**
 *  Complete session state. Returned by `start_session` / `get_session` and
 *  emitted as `session-changed` on lifecycle changes.
 */
export type SessionSnapshot = {
	/**
	 *  Monotonic per session; incremented on every state change the UI can observe (every
	 *  `session-changed`, `operation-prompt`, `operation-resolved`, `fault-changed`,
	 *  `item-values-changed` batch, `realtime-status`). Events carry the same counter.
	 */
	revision: number,
	deviceId: string,
	deviceName: string,
	status: SessionStatus,
	startedAt: string,
	autoAccept: boolean,
	realisticMode: boolean,
	sendIntervalSec: number,
	/**
	 *  Last successful measurement send (ISO-8601); a `session-changed` follows every
	 *  periodic send.
	 */
	lastSentAt: string | null,
	realtimeConnected: boolean,
	/**
	 *  The device's setup was edited during the session in a way the running session cannot
	 *  take over (item selection, custom items / slaves, digital input type): restart to apply.
	 */
	restartNeeded: boolean,
	items: ItemRuntimeState[],
	groups: DaliGroupState[],
	activeFaults: ActiveFault[],
	pendingOperations: OperationPrompt[],
};

/**  Lifecycle of the (single) session. */
export type SessionStatus = "starting" | "running" | "stopping" | "stopped" | 
/**  Stopped because of an unrecoverable error (see `SessionError` event). */
"failed";

/**
 *  Arguments of `set_item_value`. A struct because specta cannot annotate a bare `f64`
 *  command argument (it would become `number | null`).
 */
export type SetItemValueRequest = {
	itemId: string,
	value: number,
};

/**  Cumulocity alarm severity. */
export type Severity = "CRITICAL" | "MAJOR" | "MINOR" | "WARNING";

/**  A custom alarm of a slave (`lw_demo_<id:02>_<name>`, D2). A slave carries any number. */
export type SlaveAlarmDefinition = {
	/**  `[A-Za-z0-9_-]`; used in the alarm type and as the fault target. */
	name: string,
	text: string,
	severity: Severity,
};

/**
 *  Modbus slave assignment (IDs count down from 20, addresses from 240) plus the register
 *  addresses assigned within it. Stored in `lw_demo.slaves`; existing entries are never
 *  renumbered (`payload::naming::assign_slaves` / `assign_registers`).
 */
export type SlaveAssignment = {
	/**  Slave key (library [`SlaveDefinition::key`] or a custom slave). */
	key: string,
	/**  Slave id 1–20. */
	id: number,
	/**  Modbus slave address 1–247. */
	address: number,
	registers?: RegisterAssignment[],
};

/**  A Modbus slave = one functional group (PRD §7.4, §11.3). */
export type SlaveDefinition = {
	key: string,
	/**  ≤ 19 UTF-8 bytes (firmware buffer). */
	name: string,
	/**  Request interval in seconds (written to `lw_configModbusSlaves`). */
	requestInterval: number,
	/**  Custom alarms of this slave (D2). */
	alarms?: SlaveAlarmDefinition[],
};

/**  Arguments of `start_session`. */
export type StartSessionRequest = {
	deviceId: string,
	/**  Take over a fresh advisory lock held by someone else. */
	force: boolean,
	/**  Auto-accept visible operations (off by default). */
	autoAccept: boolean,
};

/**  Which system measurement a `system` item simulates. */
export type SystemKind = 
/**  `c8y_SignalStrength.rssi`, unit `dBm`. */
"rssi" | 
/**  `c8y_TemperatureMeasurement.T`, unit `C`. */
"temperature";

/**
 *  The Cumulocity tenant a login goes to. Entered by the user (tenant id + URL); nothing
 *  tenant-specific is bundled with the app.
 */
export type Tenant = {
	/**  Stable key used in commands and keychain entries: `<tenantId>@<host>`. */
	key: string,
	/**  Cumulocity tenant id, e.g. `t12345`. */
	tenantId: string,
	/**  Base URL without path or trailing slash, e.g. `https://example.cumulocity.com`. */
	baseUrl: string,
};

/**  Arguments of `update_demo_device`. `None` = unchanged. */
export type UpdateDeviceRequest = {
	name: string | null,
	description: string | null,
	position: Position | null,
};

/**  Diff between a device's demo and the bundled library (PRD §14). */
export type UpgradePreview = {
	fromVersion: string,
	toVersion: string,
	itemsAdded: string[],
	itemsRemoved: string[],
	itemsChanged: string[],
	floorplansAdded: string[],
	floorplansRemoved: string[],
	floorplansChanged: string[],
	/**
	 *  Floorplans of the device with the same name as an added / changed layout that the app did
	 *  not create. The upgrade never touches them: the layout is skipped.
	 */
	floorplanConflicts: FloorplanRef[],
	/**
	 *  Names of app-created floorplans somebody edited on the device. The upgrade keeps them and
	 *  creates the new layout next to them as `<name> (v<version>)`.
	 */
	floorplansEdited: string[],
	/**
	 *  Demo-pack level fields the upgrade takes from the new library (the device still had the
	 *  value that was applied): `tags`, `includes`, `excludes`, `daliLampCount`, `daliGroups`,
	 *  `digitalInputs`, `sendIntervalSec`.
	 */
	demoChanges: string[],
	/**  Fields whose library value changed but that were changed on the device: kept as they are. */
	keptOverrides: string[],
	/**
	 *  Custom slaves / items of the device (ids) that exist in the library now (an exported
	 *  pack was released). The library version is used from now on.
	 */
	customNowInLibrary: string[],
};

/**  Operations that need presenter confirmation ("visible operations"). */
export type VisibleOperationKind = 
/**  `lw_switchGroupMode` */
"switchGroupMode" | 
/**  `lw_switchConverterState` */
"switchConverterState" | 
/**  `lw_modbusWrite` */
"modbusWrite";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

